# Stage 6: review
# --------------------------------------------------------------------------
def fallback_review(validation_results: dict) -> dict:
    """Build a review from the static validation results already collected."""
    findings = []
    counter = 0
    for path, result in (validation_results or {}).items():
        for error in result.get("errors", []):
            counter += 1
            findings.append({
                "finding_id": f"RV-{counter:03d}",
                "severity": "critical",
                "category": "correctness",
                "layer": _layer_from_path(path),
                "file": path,
                "summary": error,
                "recommendation": "Fix the reported construct and regenerate the module.",
            })
        for warning in result.get("warnings", []):
            counter += 1
            findings.append({
                "finding_id": f"RV-{counter:03d}",
                "severity": "low",
                "category": "readability",
                "layer": _layer_from_path(path),
                "file": path,
                "summary": warning,
                "recommendation": "Address before promotion to the shared workspace.",
            })

    critical = any(item["severity"] in ("critical", "high") for item in findings)
    return {
        "verdict": "request_changes" if critical else "approve_with_comments",
        "findings": findings,
        "summary": (
            f"{FALLBACK_BANNER} Static validation produced {len(findings)} "
            "finding(s); a human review is still required because the review "
            "agent did not return a parseable verdict."
        ),
        "_generated_by": "fallback",
    }


def _layer_from_path(path: str) -> str:
    for layer in config.LAYERS:
        if layer.lower() in str(path).lower():
            return layer
    return "L1"
